@dataclass
class ResearchState:
    task_id: str
    query: str
    start_time: float
    current_depth: int
    max_depth: int
    findings: List[Dict]
    hypotheses: List[str]
    searches_performed: int
    status: str
    final_report: Optional[str] = None

class DeepSearchAgent:
    def __init__(self):
        # Validate required environment variables
        required_vars = [
            "EXA_API_KEY",
            "CEREBRAS_API_KEY",
            "AWS_ACCESS_KEY_ID",
            "AWS_SECRET_ACCESS_KEY",
            "XAI_API_KEY",
            "DRAGONFLY_REDIS_URL",
            "BABY_URI"
        ]

        missing_vars = [var for var in required_vars if not os.environ.get(var)]
        if missing_vars:
            raise ValueError(
                f"Missing required environment variables: {', '.join(missing_vars)}\n"
                f"Please set these in the Secrets tool (Tools > Secrets)"
            )

        self.exa = Exa(api_key=os.environ.get("EXA_API_KEY"))
        self.cerebras = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))
        self.bedrock_client = AnthropicBedrock(
            aws_access_key=os.environ.get("AWS_ACCESS_KEY_ID"),
            aws_secret_key=os.environ.get("AWS_SECRET_ACCESS_KEY"),
            aws_region="us-east-1"
        )
        self.redis_primary = redis.from_url(os.environ.get("DRAGONFLY_REDIS_URL"), decode_responses=True)
        self.redis_secondary = redis.from_url(os.environ.get("BABY_URI"), decode_responses=True)
        self.max_research_time = 5400
        self.max_search_depth = 15

    def _call_grok(self, messages: List[Dict], max_tokens: int = 131072, temperature: float = 0.7) -> str:
        headers = {
            "Authorization": f"Bearer {os.environ.get('XAI_API_KEY')}",
            "Content-Type": "application/json"
        }
        response = requests.post(
            "",
            headers=headers,
            json={
                "model": "grok-4-fast",
                "messages": messages,
                "max_tokens": max_tokens,
                "temperature": temperature
            }
        )
        return response.json()["choices"][0]["message"]["content"]

    def _call_cerebras_thinking(self, messages: List[Dict], model: str = "qwen-3-235b-a22b-thinking-2507") -> str:
        response = self.cerebras.chat.completions.create(
            model=model,
            messages=messages,
            max_tokens=131072,
            temperature=0.8
        )
        return response.choices[0].message.content

    def _call_cerebras_standard(self, messages: List[Dict], model: str = "gpt-oss-120b") -> str:
        response = self.cerebras.chat.completions.create(
            model=model,
            messages=messages,
            max_tokens=131072,
            temperature=0.7
        )
        return response.choices[0].message.content

    def _call_claude(self, messages: List[Dict], max_tokens: int = 200000) -> str:
        system_message = None
        anthropic_messages = []
        for msg in messages:
            if msg["role"] == "system":
                system_message = msg["content"]
            else:
                anthropic_messages.append({"role": msg["role"], "content": msg["content"]})
        kwargs = {
            "model": "us.anthropic.claude-sonnet-4-5-20250929-v1:0",
            "messages": anthropic_messages,
            "max_tokens": max_tokens,
            "temperature": 0.7
        }
        if system_message:
            kwargs["system"] = system_message
        response = self.bedrock_client.messages.create(**kwargs)
        return response.content[0].text

    def _save_state(self, state: ResearchState):
        key = f"research:{state.task_id}"
        self.redis_primary.set(key, json.dumps(asdict(state)), ex=7200)
        self.redis_secondary.set(key, json.dumps(asdict(state)), ex=7200)

    def _load_state(self, task_id: str) -> Optional[ResearchState]:
        key = f"research:{task_id}"
        data = self.redis_primary.get(key)
        if not data:
            data = self.redis_secondary.get(key)
        if data:
            return ResearchState(**json.loads(data))
        return None

    def _save_finding(self, task_id: str, finding: Dict):
        key = f"findings:{task_id}"
        self.redis_primary.rpush(key, json.dumps(finding))
        self.redis_secondary.rpush(key, json.dumps(finding))
        self.redis_primary.expire(key, 7200)
        self.redis_secondary.expire(key, 7200)

    def _get_all_findings(self, task_id: str) -> List[Dict]:
        key = f"findings:{task_id}"
        findings = self.redis_primary.lrange(key, 0, -1)
        if not findings:
            findings = self.redis_secondary.lrange(key, 0, -1)
        return [json.loads(f) for f in findings]

    def _exa_search_comprehensive(self, query: str, category: Optional[str] = None) -> List[Dict]:
        results = []
        try:
            response = self.exa.search_and_contents(
                query=query,
                type="auto",
                num_results=100,
                text=True,
                highlights=True,
                category=category,
                livecrawl="preferred"
            )
            for result in response.results:
                results.append({
                    "url": result.url,
                    "title": result.title,
                    "text": result.text if hasattr(result, 'text') else "",
                    "highlights": result.highlights if hasattr(result, 'highlights') else [],
                    "published_date": result.published_date if hasattr(result, 'published_date') else None,
                    "author": result.author if hasattr(result, 'author') else None
                })
        except Exception as e:
            print(f"Exa search error: {e}")
        return results

    def _exa_find_similar(self, url: str) -> List[Dict]:
        results = []
        try:
            response = self.exa.find_similar_and_contents(
                url=url,
                num_results=100,
                text=True,
                exclude_source_domain=True
            )
            for result in response.results:
                results.append({
                    "url": result.url,
                    "title": result.title,
                    "text": result.text if hasattr(result, 'text') else ""
                })
        except Exception as e:
            print(f"Exa similar search error: {e}")
        return results

    def _exa_get_contents(self, urls: List[str]) -> List[Dict]:
        results = []
        try:
            response = self.exa.get_contents(
                ids=urls,
                text=True,
                livecrawl="always",
                subpages=9,
                subpage_target=["article", "blog", "news", "research"]
            )
            for result in response.results:
                results.append({
                    "url": result.url,
                    "title": result.title,
                    "text": result.text if hasattr(result, 'text') else ""
                })
        except Exception as e:
            print(f"Exa contents error: {e}")
        return results

    def _analyze_initial_query(self, query: str) -> Dict:
        prompt = f"""Analyze this research query and provide a structured analysis:
Query: {query}

Provide:
1. Main topic and subtopics
2. Key entities to investigate
3. 5 initial search queries
4. Expected sources types
5. Research depth required (1-10)

Respond in JSON format with keys: main_topic, subtopics, entities, search_queries, source_types, depth_score"""

        response = self._call_cerebras_thinking([
            {"role": "system", "content": "You are an expert research analyst. Provide detailed analysis in JSON format."},
            {"role": "user", "content": prompt}
        ])

        try:
            return json.loads(response)
        except:
            return {
                "main_topic": query,
                "subtopics": [],
                "entities": [],
                "search_queries": [query],
                "source_types": ["news", "research paper", "company"],
                "depth_score": 5
            }

    def _generate_hypotheses(self, query: str, findings: List[Dict]) -> List[str]:
        findings_text = "\n".join([f"- {f.get('summary', '')[:200]}" for f in findings[:20]])
        prompt = f"""Based on the research query and current findings, generate 5 hypotheses to investigate:

Query: {query}

Current findings:
{findings_text}

Generate 5 specific, testable hypotheses that would deepen our understanding."""

        response = self._call_claude([
            {"role": "user", "content": prompt}
        ])

        hypotheses = []
        for line in response.split("\n"):
            if line.strip() and (line.strip()[0].isdigit() or line.strip().startswith("-")):
                cleaned = line.strip().lstrip("0123456789.-) ")
                if cleaned:
                    hypotheses.append(cleaned)
        return hypotheses[:5]

    def _formulate_search_queries(self, hypothesis: str, context: Dict) -> List[str]:
        prompt = f"""Generate 3 specific search queries to investigate this hypothesis:

Hypothesis: {hypothesis}

Context: {json.dumps(context, indent=2)}

Provide 3 diverse search queries that would find relevant information."""

        response = self._call_grok([
            {"role": "system", "content": "You are a search query expert. Generate precise, diverse queries."},
            {"role": "user", "content": prompt}
        ])

        queries = []
        for line in response.split("\n"):
            if line.strip() and (line.strip()[0].isdigit() or line.strip().startswith("-")):
                cleaned = line.strip().lstrip("0123456789.-) ")
                if cleaned:
                    queries.append(cleaned)
        return queries[:3]

    def _synthesize_findings(self, findings: List[Dict]) -> str:
        findings_text = "\n\n".join([
            f"Source: {f.get('title', 'Unknown')}\nURL: {f.get('url', '')}\nSummary: {f.get('summary', '')}"
            for f in findings[:30]
        ])

        prompt = f"""Synthesize these research findings into a comprehensive analysis:

{findings_text}

Provide:
1. Key themes and patterns
2. Contradictions or gaps
3. Most important insights
4. Areas requiring deeper investigation"""

        return self._call_claude([
            {"role": "user", "content": prompt}
        ])

    def _decide_next_action(self, state: ResearchState) -> str:
        elapsed = time.time() - state.start_time

        if elapsed > self.max_research_time * 0.9:
            return "finalize"

        if state.searches_performed > 500:
            return "finalize"

        if state.current_depth >= state.max_depth:
            return "finalize"

        if len(state.findings) < 50:
            return "broad_search"

        if len(state.hypotheses) < state.current_depth * 3:
            return "generate_hypotheses"

        return "deep_dive"

    def _evaluate_findings_quality(self, findings: List[Dict]) -> float:
        if not findings:
            return 0.0

        total_score = 0
        for f in findings[:50]:
            score = 0
            if f.get("text") and len(f.get("text", "")) > 500:
                score += 0.3
            if f.get("published_date"):
                score += 0.2
            if f.get("author"):
                score += 0.2
            if f.get("highlights"):
                score += 0.3
            total_score += score

        return total_score / min(len(findings), 50)

    def _perform_broad_search(self, state: ResearchState, analysis: Dict):
        queries = analysis.get("search_queries", [state.query])

        for query in queries[:5]:
            for category in [None, "news", "research paper", "company"]:
                results = self._exa_search_comprehensive(query, category)

                for result in results[:20]:
                    finding = {
                        "query": query,
                        "category": category,
                        "depth": state.current_depth,
                        "timestamp": datetime.now().isoformat(),
                        **result
                    }
                    state.findings.append(finding)
                    self._save_finding(state.task_id, finding)
                    state.searches_performed += 1

                time.sleep(0.1)

    def _perform_deep_dive(self, state: ResearchState):
        hypothesis = state.hypotheses[state.current_depth % len(state.hypotheses)]

        context = {
            "main_query": state.query,
            "current_findings_count": len(state.findings),
            "current_depth": state.current_depth
        }

        queries = self._formulate_search_queries(hypothesis, context)

        for query in queries:
            results = self._exa_search_comprehensive(query)

            for result in results[:15]:
                finding = {
                    "query": query,
                    "hypothesis": hypothesis,
                    "depth": state.current_depth,
                    "timestamp": datetime.now().isoformat(),
                    **result
                }
                state.findings.append(finding)
                self._save_finding(state.task_id, finding)
                state.searches_performed += 1

                if result.get("url"):
                    similar = self._exa_find_similar(result["url"])
                    for sim in similar[:5]:
                        sim_finding = {
                            "query": query,
                            "source": "similar_to_" + result["url"],
                            "depth": state.current_depth + 0.5,
                            "timestamp": datetime.now().isoformat(),
                            **sim
                        }
                        state.findings.append(sim_finding)
                        self._save_finding(state.task_id, sim_finding)
                        state.searches_performed += 1

            time.sleep(0.2)

    def _generate_final_report(self, state: ResearchState, analysis: Dict) -> str:
        all_findings = self._get_all_findings(state.task_id)

        synthesis = self._synthesize_findings(all_findings)

        findings_by_depth = {}
        for f in all_findings:
            depth = f.get("depth", 0)
            if depth not in findings_by_depth:
                findings_by_depth[depth] = []
            findings_by_depth[depth].append(f)

        report_sections = []

        report_sections.append(f"# Deep Research Report: {state.query}\n")
        report_sections.append(f"\n**Generated:** {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
        report_sections.append(f"\n**Research Duration:** {(time.time() - state.start_time)/60:.1f} minutes")
        report_sections.append(f"\n**Total Sources:** {len(all_findings)}")
        report_sections.append(f"\n**Searches Performed:** {state.searches_performed}")
        report_sections.append(f"\n**Research Depth:** {state.current_depth}/{state.max_depth}\n")

        report_sections.append("\n## Executive Summary\n")
        exec_summary_prompt = f"""Write a 3-paragraph executive summary for this research:

Query: {state.query}

Main Analysis:
{synthesis[:3000]}

Total findings: {len(all_findings)}"""

        exec_summary = self._call_claude([{"role": "user", "content": exec_summary_prompt}])
        report_sections.append(exec_summary)

        report_sections.append("\n## Main Analysis\n")
        report_sections.append(synthesis)

        report_sections.append("\n## Key Findings by Research Depth\n")
        for depth in sorted(findings_by_depth.keys())[:10]:
            findings = findings_by_depth[depth][:10]
            report_sections.append(f"\n### Depth Level {depth}\n")
            for i, f in enumerate(findings, 1):
                report_sections.append(f"\n{i}. **{f.get('title', 'Untitled')}**")
                report_sections.append(f"\n   - URL: {f.get('url', 'N/A')}")
                if f.get('published_date'):
                    report_sections.append(f"\n   - Published: {f['published_date']}")
                if f.get('author'):
                    report_sections.append(f"\n   - Author: {f['author']}")
                summary = f.get('text', '')[:300]
                if summary:
                    report_sections.append(f"\n   - Summary: {summary}...")

        report_sections.append("\n## Hypotheses Investigated\n")
        for i, hyp in enumerate(state.hypotheses, 1):
            report_sections.append(f"\n{i}. {hyp}")

        report_sections.append("\n## Detailed Source Analysis\n")
        for i, finding in enumerate(all_findings[:100], 1):
            report_sections.append(f"\n### Source {i}: {finding.get('title', 'Untitled')}\n")
            report_sections.append(f"- **URL:** {finding.get('url', 'N/A')}")
            report_sections.append(f"- **Query:** {finding.get('query', 'N/A')}")
            report_sections.append(f"- **Depth:** {finding.get('depth', 0)}")
            if finding.get('published_date'):
                report_sections.append(f"- **Published:** {finding['published_date']}")
            if finding.get('author'):
                report_sections.append(f"- **Author:** {finding['author']}")

            text = finding.get('text', '')
            if text:
                report_sections.append(f"\n**Content:**\n{text[:1000]}\n")

            highlights = finding.get('highlights', [])
            if highlights:
                report_sections.append("\n**Key Highlights:**")
                for hl in highlights[:5]:
                    report_sections.append(f"- {hl}")

        report_sections.append("\n## Methodology\n")
        report_sections.append(f"""
This research was conducted using an autonomous deep search agent with the following characteristics:

- **Search Engine:** Exa AI (neural + keyword search)
- **AI Models:** 
  - Cerebras GPT-OSS-120B (fast reasoning)
  - Cerebras Qwen-3-235B Thinking (deep analysis)
  - AWS Bedrock Claude Sonnet 4.5 (synthesis)
  - xAI Grok-4-Fast (query generation)
- **Data Storage:** Dragonfly Redis (dual redundancy)
- **Search Strategy:** Multi-depth iterative investigation
- **Max Research Time:** {self.max_research_time/60} minutes
- **Max Search Depth:** {self.max_search_depth} levels

The agent autonomously:
1. Analyzed the initial query
2. Generated hypotheses
3. Formulated targeted search queries
4. Collected and analyzed sources
5. Performed similarity searches
6. Synthesized findings across multiple depths
""")

        report_sections.append("\n## Conclusion\n")
        conclusion_prompt = f"""Write a comprehensive conclusion for this research report:

Original Query: {state.query}

Key Statistics:
- Sources analyzed: {len(all_findings)}
- Research depth: {state.current_depth} levels
- Duration: {(time.time() - state.start_time)/60:.1f} minutes

Main findings summary:
{synthesis[:2000]}

Write a 2-paragraph conclusion that summarizes the research outcome and suggests future research directions."""

        conclusion = self._call_claude([{"role": "user", "content": conclusion_prompt}])
        report_sections.append(conclusion)

        report_sections.append(f"\n\n---\n*Report generated by DeepSearch Agent v1.0*\n")
        report_sections.append(f"*Total words: {sum(len(s.split()) for s in report_sections)}*\n")

        return "".join(report_sections)

    def run_autonomous_research(self, query: str, task_id: Optional[str] = None) -> str:
        if not task_id:
            task_id = f"task_{int(time.time())}_{hash(query) % 10000}"

        analysis = self._analyze_initial_query(query)

        state = ResearchState(
            task_id=task_id,
            query=query,
            start_time=time.time(),
            current_depth=0,
            max_depth=min(analysis.get("depth_score", 5) * 2, self.max_search_depth),
            findings=[],
            hypotheses=[],
            searches_performed=0,
            status="running"
        )

        self._save_state(state)

        print(f"Starting autonomous research for: {query}")
        print(f"Task ID: {task_id}")
        print(f"Max depth: {state.max_depth}")

        try:
            self._perform_broad_search(state, analysis)
            self._save_state(state)

            while True:
                elapsed = time.time() - state.start_time

                if elapsed > self.max_research_time:
                    print("Max research time reached")
                    break

                action = self._decide_next_action(state)
                print(f"Depth {state.current_depth}, Action: {action}, Findings: {len(state.findings)}, Elapsed: {elapsed/60:.1f}min")

                if action == "finalize":
                    break
                elif action == "generate_hypotheses":
                    hypotheses = self._generate_hypotheses(state.query, state.findings)
                    state.hypotheses.extend(hypotheses)
                    print(f"Generated {len(hypotheses)} new hypotheses")
                elif action == "deep_dive":
                    if state.hypotheses:
                        self._perform_deep_dive(state)
                        state.current_depth += 1
                    else:
                        state.hypotheses = self._generate_hypotheses(state.query, state.findings)
                elif action == "broad_search":
                    self._perform_broad_search(state, analysis)

                self._save_state(state)

                quality = self._evaluate_findings_quality(state.findings)
                print(f"Findings quality score: {quality:.2f}")

                time.sleep(0.5)

            print("Generating final report...")
            state.status = "finalizing"
            self._save_state(state)

            final_report = self._generate_final_report(state, analysis)

            state.final_report = final_report
            state.status = "completed"
            self._save_state(state)

            print(f"Research completed! Total findings: {len(state.findings)}")
            print(f"Report length: {len(final_report.split())} words")

            return final_report

        except Exception as e:
            print(f"Error during research: {e}")
            state.status = "error"
            self._save_state(state)
            raise

