            body {{
                font-family: 'Inter', sans-serif;
                max-width: 900px;
                margin: 0 auto;
                padding: 40px 20px;
                background: #0a0a0a;
                color: #ffffff;
                line-height: 1.6;
            }}
            h1, h2, h3 {{ color: #00d4ff; }}
            a {{ color: #00d4ff; }}
            code {{ background: rgba(255,255,255,0.1); padding: 2px 6px; border-radius: 4px; }}
            pre {{ background: rgba(255,255,255,0.05); padding: 15px; border-radius: 8px; overflow-x: auto; }}
        </style>
    </head>
    <body>
        {html_content}
    </body>
    </html>
    """

    return html_template

@app.get("/report/pdf")
async def get_report_pdf():
    return JSONResponse({"error": "PDF generation not implemented yet. Please use HTML view."})

def main():
    print("Starting DeepSearch AI server on port 5000...")
    uvicorn.run(app, host="0.0.0.0", port=5000)

if __name__ == "__main__":
    main()

